/**
* All available permissions
*/
const ALL_PERMISSIONS = [
	"pattern:read",
	"pattern:write",
	"pattern:delete",
	"detection:detect",
	"detection:redact",
	"detection:restore",
	"audit:read",
	"audit:export",
	"audit:delete",
	"metrics:read",
	"metrics:export",
	"metrics:reset",
	"config:read",
	"config:write"
];
/**
* Admin role - full access to all operations
*/
const ADMIN_ROLE = {
	name: "admin",
	description: "Administrator with full access to all operations",
	permissions: ALL_PERMISSIONS
};
/**
* Analyst role - can perform analysis and read audit/metrics
*/
const ANALYST_ROLE = {
	name: "analyst",
	description: "Data analyst with detection, audit, and metrics access",
	permissions: [
		"pattern:read",
		"detection:detect",
		"detection:redact",
		"detection:restore",
		"audit:read",
		"audit:export",
		"metrics:read",
		"metrics:export",
		"config:read"
	]
};
/**
* Operator role - can perform detections and basic operations
*/
const OPERATOR_ROLE = {
	name: "operator",
	description: "Operator with detection and limited audit/metrics access",
	permissions: [
		"pattern:read",
		"detection:detect",
		"detection:redact",
		"audit:read",
		"metrics:read"
	]
};
/**
* Viewer role - read-only access to patterns, audit logs, and metrics
*/
const VIEWER_ROLE = {
	name: "viewer",
	description: "Read-only viewer with no execution permissions",
	permissions: [
		"pattern:read",
		"audit:read",
		"audit:export",
		"metrics:read",
		"metrics:export",
		"config:read"
	]
};
/**
* Get predefined role by name
*/
function getPredefinedRole(roleName) {
	switch (roleName.toLowerCase()) {
		case "admin": return ADMIN_ROLE;
		case "analyst": return ANALYST_ROLE;
		case "operator": return OPERATOR_ROLE;
		case "viewer": return VIEWER_ROLE;
		default: return;
	}
}

