//#region src/utils/redaction-strategies.ts
/**
* Apply redaction based on mode
*/
function applyRedactionMode(value, type, mode, placeholder) {
	switch (mode) {
		case "placeholder": return placeholder;
		case "mask-middle": return maskMiddle(value, type);
		case "mask-all": return "*".repeat(value.length);
		case "format-preserving": return formatPreserving(value, type);
		case "token-replace": return tokenReplace(value, type);
		default: return placeholder;
	}
}
/**
* Mask middle characters while preserving edges
* Examples:
* - Email: j***@example.com
* - Phone: 555-**-1234
* - SSN: ***-**-1234
* - Credit Card: 4532-****-****-1234
*/
function maskMiddle(value, type) {
	if (type.includes("EMAIL")) {
		const atIndex = value.indexOf("@");
		if (atIndex > 0) {
			const username = value.substring(0, atIndex);
			const domain = value.substring(atIndex);
			return (username.length <= 2 ? "*".repeat(username.length) : username[0] + "*".repeat(username.length - 1)) + domain;
		}
	}
	if (type.includes("PHONE")) {
		const digits = value.replace(/\D/g, "");
		if (digits.length >= 10) {
			const areaCode = digits.substring(0, 3);
			const lastFour = digits.substring(digits.length - 4);
			const middleCount = digits.length - 7;
			return `${areaCode}-${"*".repeat(middleCount > 0 ? middleCount : 2)}-${lastFour}`;
		}
	}
	if (type === "SSN") {
		const digits = value.replace(/\D/g, "");
		if (digits.length === 9) return `***-**-${digits.substring(5)}`;
	}
	if (type === "CREDIT_CARD") {
		const digits = value.replace(/\D/g, "");
		if (digits.length >= 13) {
			const first = digits.substring(0, 4);
			const last = digits.substring(digits.length - 4);
			const middleGroups = Math.floor((digits.length - 8) / 4);
			return `${first}-${("****-".repeat(middleGroups) + "****").substring(0, digits.length - 8)}-${last}`;
		}
	}
	if (value.length <= 4) return "*".repeat(value.length);
	const showCount = Math.min(2, Math.floor(value.length * .2));
	const first = value.substring(0, showCount);
	const last = value.substring(value.length - showCount);
	const maskCount = value.length - showCount * 2;
	return `${first}${"*".repeat(maskCount)}${last}`;
}
/**
* Format-preserving redaction - maintains structure
* Examples:
* - SSN: XXX-XX-XXXX
* - Phone: (XXX) XXX-XXXX
* - Email: XXXXX@XXXXXX.XXX
* - Date: XX/XX/XXXX
*/
function formatPreserving(value, type) {
	let result = "";
	for (let i = 0; i < value.length; i++) {
		const char = value[i];
		if (!/[a-zA-Z0-9]/.test(char)) result += char;
		else if (/[a-zA-Z]/.test(char)) result += char === char.toUpperCase() ? "X" : "x";
		else result += "X";
	}
	return result;
}
/**
* Token replacement - replace with realistic fake data
* Uses deterministic generation based on hash
*/
function tokenReplace(value, type) {
	const hash = simpleHash(value);
	if (type.includes("EMAIL")) {
		const domains = [
			"example.com",
			"test.com",
			"sample.org",
			"demo.net"
		];
		const usernames = [
			"user",
			"john.doe",
			"jane.smith",
			"test.account"
		];
		return `${usernames[hash % usernames.length]}${hash % 100}@${domains[hash % domains.length]}`;
	}
	if (type.includes("PHONE")) return `(555) ${hash % 900 + 100}-${hash % 9e3 + 1e3}`;
	if (type === "SSN") return `${hash % 899 + 100}-${(hash % 99 + 1).toString().padStart(2, "0")}-${(hash % 9999 + 1).toString().padStart(4, "0")}`;
	if (type === "CREDIT_CARD") return `4532-${[
		(hash % 9e3 + 1e3).toString(),
		(hash % 9e3 + 1e3).toString(),
		(hash % 9e3 + 1e3).toString()
	].join("-")}`;
	if (type.includes("NAME")) {
		const firstNames = [
			"John",
			"Jane",
			"Alex",
			"Sam",
			"Chris",
			"Pat"
		];
		const lastNames = [
			"Smith",
			"Johnson",
			"Williams",
			"Brown",
			"Jones",
			"Davis"
		];
		return `${firstNames[hash % firstNames.length]} ${lastNames[(hash >> 4) % lastNames.length]}`;
	}
	return `[REDACTED_${type}]`;
}
/**
* Simple hash function for deterministic token generation
*/
function simpleHash(str) {
	let hash = 0;
	for (let i = 0; i < str.length; i++) {
		const char = str.charCodeAt(i);
		hash = (hash << 5) - hash + char;
		hash = hash & hash;
	}
	return Math.abs(hash);
}

